ed","short_description":"Sport Apple Watch Band - Red. Size: 42/44mm.","condition_label":"Brand New","compatibility":"Apple Watch cases compatible with 42/44 mm","cost_price":3.85,"retail_price":35,"image_url":"https://dghyt15qon7us.cloudfront.net/images/productTheme/Inventory/small/1641974148.jpg","stock_quantity":0,"is_visible":false,"is_pos_visible":true,"upc":"00000000034","variant_name":"42/44mm","variant_color":"Red","source_system":"repairdesk_watch_bands","source_external_id":"6133","source_category_path":"9.1 Watch Band > Sport Band","import_status":"active","product_group_code":"TM8-GRP-WB-SPORT-RED","source_metadata":{"original_name":"42/44 Sport Apple Watch Band Red","original_sku":"00000000034","source_stock":2,"proposed_stock":0,"inventory_assignment":"none","source_pos_visible":true,"watch_band_family":"Sport Band","watch_band_color":"Red","watch_band_size":"42/44mm","cost_status":"valid","cost_source":"repairdesk_source","image_status":"available","source_row":39}}]$watch_bands$::jsonb) as x(
  sku text,
  slug text,
  name text,
  brand text,
  model text,
  short_description text,
  condition_label text,
  compatibility text,
  cost_price numeric,
  retail_price numeric,
  image_url text,
  stock_quantity integer,
  is_visible boolean,
  is_pos_visible boolean,
  upc text,
  variant_name text,
  variant_color text,
  source_system text,
  source_external_id text,
  source_category_path text,
  import_status text,
  product_group_code text,
  source_metadata jsonb
);

do $$
begin
  if (select count(*) from watch_band_group_input) <> 35 then
    raise exception 'Watch band import expected 35 grouped styles.';
  end if;

  if (select count(*) from watch_band_product_input) <> 61 then
    raise exception 'Watch band import expected 61 size variants.';
  end if;

  if not exists (
    select 1 from public.categories where slug = 'watch-accessories'
  ) or not exists (
    select 1
    from public.pos_category_taxonomy
    where category_name = 'Watch Accessories'
      and subcategory_name = 'Watch Bands'
      and active
  ) then
    raise exception 'Watch band import references a missing database or POS category.';
  end if;

  if exists (
    select 1
    from watch_band_group_input input
    where coalesce(btrim(input.code), '') = ''
       or coalesce(btrim(input.slug), '') = ''
       or coalesce(btrim(input.name), '') = ''
       or coalesce(btrim(input.main_image_url), '') = ''
       or input.product_family <> 'watch_band'
  ) then
    raise exception 'Watch band import contains an invalid product group.';
  end if;

  if exists (
    select 1
    from watch_band_product_input input
    where input.cost_price <= 0
       or input.retail_price <= 0
       or coalesce(btrim(input.image_url), '') = ''
       or coalesce(btrim(input.variant_name), '') = ''
       or coalesce(btrim(input.variant_color), '') = ''
       or input.stock_quantity <> 0
       or input.is_visible
       or not input.is_pos_visible
  ) then
    raise exception 'Watch band import contains an invalid cost, price, image, size, colour, stock, or visibility value.';
  end if;

  if exists (
    select input.sku
    from watch_band_product_input input
    group by input.sku
    having count(*) > 1
  ) or exists (
    select input.source_external_id
    from watch_band_product_input input
    group by input.source_system, input.source_external_id
    having count(*) > 1
  ) or exists (
    select input.product_group_code, lower(input.variant_name)
    from watch_band_product_input input
    group by input.product_group_code, lower(input.variant_name)
    having count(*) > 1
  ) then
    raise exception 'Watch band import contains a duplicate SKU, source item, or size within a style.';
  end if;

  if exists (
    select 1
    from watch_band_group_input input
    join public.product_groups existing on existing.slug = input.slug
    where existing.code <> input.code
  ) then
    raise exception 'Watch band import found a group slug owned by another product group.';
  end if;

  if exists (
    select 1
    from watch_band_group_input input
    join public.product_groups existing on existing.code = input.code
    where existing.product_family <> 'watch_band'
  ) then
    raise exception 'Watch band import found a group code owned by another product family.';
  end if;

  if exists (
    select 1
    from watch_band_product_input input
    join public.products existing on existing.sku = input.sku
    where existing.source_system is distinct from input.source_system
       or existing.source_external_id is distinct from input.source_external_id
  ) then
    raise exception 'Watch band import found an SKU owned by another source product.';
  end if;

  if exists (
    select 1
    from watch_band_product_input input
    join public.products existing on existing.upc = input.upc
    where existing.source_system is distinct from input.source_system
       or existing.source_external_id is distinct from input.source_external_id
  ) then
    raise exception 'Watch band import found a barcode owned by another source product.';
  end if;

  if exists (
    select 1
    from watch_band_product_input input
    join public.products existing
      on existing.source_system = input.source_system
     and existing.source_external_id = input.source_external_id
    where existing.sku <> input.sku
  ) then
    raise exception 'Watch band import found an existing source item with another SKU.';
  end if;
end
$$;

insert into public.product_groups (
  code,
  slug,
  name,
  category_id,
  product_family,
  main_image_url,
  status,
  is_pos_visible,
  is_visible,
  pos_category_id,
  pos_sort_order
)
select
  input.code,
  input.slug,
  input.name,
  category.id,
  input.product_family,
  input.main_image_url,
  'active',
  true,
  false,
  taxonomy.id,
  input.pos_sort_order
from watch_band_group_input input
join public.categories category on category.slug = 'watch-accessories'
join public.pos_category_taxonomy taxonomy
  on taxonomy.category_name = 'Watch Accessories'
 and taxonomy.subcategory_name = 'Watch Bands'
 and taxonomy.active
on conflict (code) do update
set slug = excluded.slug,
    name = excluded.name,
    category_id = excluded.category_id,
    product_family = excluded.product_family,
    main_image_url = excluded.main_image_url,
    status = 'active',
    is_pos_visible = true,
    is_visible = false,
    pos_category_id = excluded.pos_category_id,
    pos_sort_order = excluded.pos_sort_order,
    updated_at = timezone('utc'::text, now())
where public.product_groups.product_family = 'watch_band';

insert into public.products (
  sku,
  slug,
  name,
  brand,
  model,
  category_id,
  pos_category_id,
  short_description,
  condition_label,
  compatibility,
  cost_price,
  retail_price,
  image_url,
  stock_quantity,
  is_visible,
  is_pos_visible,
  upc,
  product_group_id,
  variant_name,
  variant_color,
  source_system,
  source_external_id,
  source_category_path,
  import_status,
  source_metadata
)
select
  input.sku,
  input.slug,
  input.name,
  input.brand,
  input.model,
  category.id,
  taxonomy.id,
  input.short_description,
  input.condition_label,
  input.compatibility,
  input.cost_price,
  input.retail_price,
  input.image_url,
  0,
  false,
  true,
  input.upc,
  product_group.id,
  input.variant_name,
  input.variant_color,
  input.source_system,
  input.source_external_id,
  input.source_category_path,
  input.import_status,
  input.source_metadata
from watch_band_product_input input
join public.categories category on category.slug = 'watch-accessories'
join public.pos_category_taxonomy taxonomy
  on taxonomy.category_name = 'Watch Accessories'
 and taxonomy.subcategory_name = 'Watch Bands'
 and taxonomy.active
join public.product_groups product_group on product_group.code = input.product_group_code
on conflict (sku) do update
set slug = excluded.slug,
    name = excluded.name,
    brand = excluded.brand,
    model = excluded.model,
    category_id = excluded.category_id,
    pos_category_id = excluded.pos_category_id,
    short_description = excluded.short_description,
    condition_label = excluded.condition_label,
    compatibility = excluded.compatibility,
    cost_price = excluded.cost_price,
    retail_price = excluded.retail_price,
    image_url = excluded.image_url,
    is_visible = false,
    is_pos_visible = true,
    upc = excluded.upc,
    product_group_id = excluded.product_group_id,
    variant_name = excluded.variant_name,
    variant_color = excluded.variant_color,
    source_category_path = excluded.source_category_path,
    import_status = excluded.import_status,
    source_metadata = excluded.source_metadata,
    updated_at = timezone('utc'::text, now())
where public.products.source_system = excluded.source_system
  and public.products.source_external_id = excluded.source_external_id;

do $$
begin
  if (
    select count(*)
    from public.product_groups product_group
    join public.pos_category_taxonomy taxonomy on taxonomy.id = product_group.pos_category_id
    where product_group.code in (select input.code from watch_band_group_input input)
      and product_group.product_family = 'watch_band'
      and product_group.status = 'active'
      and product_group.is_pos_visible
      and not product_group.is_visible
      and taxonomy.category_name = 'Watch Accessories'
      and taxonomy.subcategory_name = 'Watch Bands'
  ) <> 35 then
    raise exception 'Watch band post-import validation failed for grouped styles.';
  end if;

  if (
    select count(*)
    from public.products product
    join public.product_groups product_group on product_group.id = product.product_group_id
    join public.pos_category_taxonomy taxonomy on taxonomy.id = product.pos_category_id
    where product.source_system = 'repairdesk_watch_bands'
      and product.source_external_id in (select input.source_external_id from watch_band_product_input input)
      and product.import_status = 'active'
      and product.is_pos_visible
      and not product.is_visible
      and product.stock_quantity = 0
      and product.cost_price > 0
      and product.retail_price > 0
      and coalesce(btrim(product.image_url), '') <> ''
      and product_group.product_family = 'watch_band'
      and taxonomy.category_name = 'Watch Accessories'
      and taxonomy.subcategory_name = 'Watch Bands'
  ) <> 61 then
    raise exception 'Watch band post-import validation failed for size variants.';
  end if;
end
$$;

commit;
